mapper.update:
    UPDATE MEMBER M
       SET M.CLASS_NO = #{changeNo}
         , M.UPDATED_AT = SYSDATE
     WHERE M.USER_NO = #{userNo}
       AND M.ROLE_CODE = 'COUNSELOR'
       AND NOT EXISTS (
			           SELECT 1
			             FROM MEMBER M2
			            WHERE M2.ROLE_CODE = 'COUNSELOR'
			              AND M2.STATUS = 'ACTIVE'
			              AND M2.CLASS_NO = #{changeNo}
			              AND M2.USER_NO != #{userNo}
      			 	)

UPDATE COUNSELOR_INVITE
   SET INVITE_STATUS = 'USED'
     , USER_NO = #{userNo}
 WHERE INVITE_NO = #{inviteNo}
   AND INVITE_NAME = #{inviteName}
   AND INVITE_EMAIL = #{inviteEmail}

UPDATE COUNSELOR_PROFILE
   SET CATEGORY_NO = #{changeNo}
 WHERE USER_NO = #{userNo}
